// Paste the bytecode from Remix after compiling:
// (Contracts → PancakeArbFlashLoan → Bytecode button → copy the "object" field value)
// It starts with "0x608060..."
const BYTECODE = "";

// ─── DEPLOY ───────────────────────────────────────────────────────────────────

async function main() {
  if (!PRIVATE_KEY) {
    throw new Error("Set VITE_BOT_PRIVATE_KEY in your .env file. Copy .env.example to .env and fill in your values.");
  }

  if (!BYTECODE || BYTECODE === "") {
    throw new Error("Paste the compiled bytecode from Remix into the BYTECODE variable.");
  }

  const provider = new ethers.JsonRpcProvider(BSC_RPC);
  const wallet   = new ethers.Wallet(PRIVATE_KEY, provider);

  // Confirm network
  const network = await provider.getNetwork();
  console.log(`\n🌐  Connected to chain ID: ${network.chainId}`);
  if (network.chainId !== 56n) {
    console.warn("⚠️   Warning: Expected BSC Mainnet (chain 56). Double-check your RPC.");
  }

  // Check deployer balance
  const balance = await provider.getBalance(wallet.address);
  console.log(`👛  Deployer: ${wallet.address}`);
  console.log(`💰  Balance:  ${ethers.formatEther(balance)} BNB`);

  if (balance < ethers.parseEther("0.05")) {
    console.warn("⚠️   Low BNB balance. Deployment may fail (needs ~0.01–0.05 BNB for gas).");
  }

  // Estimate gas
  const factory = new ethers.ContractFactory(ABI, BYTECODE, wallet);
  console.log("\n📦  Estimating gas...");

  let gasEstimate;
  try {
    const deployTx = await factory.getDeployTransaction();
    gasEstimate = await provider.estimateGas({ ...deployTx, from: wallet.address });
    console.log(`⛽  Estimated gas: ${gasEstimate.toString()}`);
  } catch (err) {
    throw new Error("Gas estimation failed: " + err.message);
  }

  // Get current gas price
  const feeData = await provider.getFeeData();
  const gasPrice = feeData.gasPrice;
  const estimatedCostBnb = ethers.formatEther(gasEstimate * gasPrice);
  console.log(`💸  Estimated deploy cost: ~${estimatedCostBnb} BNB`);

  // Deploy
  console.log("\n🚀  Deploying PancakeArbFlashLoan...");
  const contract = await factory.deploy({ gasLimit: gasEstimate * 120n / 100n }); // +20% buffer
  console.log(`📡  Tx sent: ${contract.deploymentTransaction().hash}`);
  console.log("⏳  Waiting for confirmation...");

  await contract.waitForDeployment();
  const address = await contract.getAddress();

  console.log("\n✅  Contract deployed successfully!");
  console.log(`📋  Contract address: ${address}`);
  console.log(`🔍  BscScan: https://bscscan.com/address/${address}`);

  // Verify owner
  const owner = await contract.owner();
  console.log(`👑  Owner:   ${owner}`);

  const refund = await contract.gasRefundUsdt();
  console.log(`⛽  Gas refund USDT: ${ethers.formatUnits(refund, 18)} USDT`);

  console.log("\n📌  Next steps:");
  console.log(`   1. Copy the address above → Dashboard → Settings → Arb Contract Address`);
  console.log(`   2. Fund the bot wallet with BNB for gas`);
  console.log(`   3. Optionally call setGasRefundUsdt() to adjust gas reimbursement`);
  console.log(`   4. Start the bot — it will use flash loans, no upfront capital needed\n`);
}

main().catch((err) => {
  console.error("\n❌  Deployment failed:", err.message || err);
});
